Certainly! Here is a minimal working example of a Qt5 C++ application that:

1. Opens a GUI for the user to select a directory.
2. Finds all Excel files (`.xlsx`, `.xls`) in the directory.
3. Converts each to CSV and saves them into a new subfolder (e.g., "csv_exports").
4. Uses [QXlsx](https://github.com/QtExcel/QXlsx) (for `.xlsx`) and [libxls](https://github.com/libxls/libxls) or [xlnt](https://github.com/tfussell/xlnt), etc., for `.xls` support.

**For simplicity, we'll focus on `.xlsx` files using [QXlsx](https://github.com/QtExcel/QXlsx) because standard Qt does not natively read Excel files.**  
Install QXlsx into your project as needed.

---

### main.cpp

```cpp
#include <QApplication>
#include <QPushButton>
#include <QFileDialog>
#include <QDir>
#include <QMessageBox>

#include "xlsxdocument.h" // QXlsx

void convertExcelToCSV(const QString& xlsxPath, const QString& csvPath) {
    QXlsx::Document xlsx(xlsxPath);
    QFile csvFile(csvPath);
    if (csvFile.open(QIODevice::WriteOnly | QIODevice::Text)) {
        QTextStream out(&csvFile);
        for (int row = 1; row <= xlsx.dimension().lastRow(); ++row) {
            QStringList fields;
            for (int col = 1; col <= xlsx.dimension().lastColumn(); ++col) {
                QVariant value = xlsx.read(row, col);
                QString text = value.toString();
                // Escape if needed
                if (text.contains(",") || text.contains("\"")) {
                    text.replace("\"", "\"\"");
                    text = "\"" + text + "\"";
                }
                fields << text;
            }
            out << fields.join(",") << "\n";
        }
    }
}

int main(int argc, char *argv[])
{
    QApplication a(argc, argv);
    QWidget window;
    window.setWindowTitle("Excel to CSV Batch Converter");

    QPushButton button("Select Folder and Convert", &window);
    QObject::connect(&button, &QPushButton::clicked, [&](){
        QString dir = QFileDialog::getExistingDirectory(&window, "Select a directory with Excel files");
        if(dir.isEmpty())
            return;

        QDir sourceDir(dir);
        QString outDirPath = dir + "/csv_exports";
        QDir().mkpath(outDirPath);

        QStringList filters;
        filters << "*.xlsx";
        QStringList excelFiles = sourceDir.entryList(filters, QDir::Files);

        if (excelFiles.isEmpty()) {
            QMessageBox::information(&window, "No Excel Files", "No .xlsx files found in the selected directory.");
            return;
        }

        for (const QString& fname : excelFiles) {
            QString xlsxPath = dir + "/" + fname;
            QString baseName = fname.section('.', 0, 0); // Remove extension
            QString csvPath = outDirPath + "/" + baseName + ".csv";
            convertExcelToCSV(xlsxPath, csvPath);
        }

        QMessageBox::information(&window, "Conversion Done", "Excel files converted to CSV in:\n" + outDirPath);
    });

    window.resize(300, 100);
    button.resize(250, 50);
    button.move(25, 25);
    window.show();
    return a.exec();
}
```

---

### CMakeLists.txt fragment

Add QXlsx:

```cmake
find_package(Qt5 COMPONENTS Core Widgets REQUIRED)
target_link_libraries(your_target Qt5::Core Qt5::Widgets QXlsx)
```

Or if using qmake, add:

```
QT += widgets
INCLUDEPATH += path/to/QXlsx/headers
LIBS += -Lpath/to/QXlsx/lib -lQXlsx
```

---

**Note about `.xls`:**  
If you want to also convert `.xls` files (old Excel format), you'll need a separate library and a different parser, as QXlsx only supports `.xlsx`. You can implement similar code with `libxls` or use an external tool for `.xls` files if necessary.

---

**Summary**  
- Requires the [QXlsx](https://github.com/QtExcel/QXlsx) library (support for `.xlsx` files only).
- This code builds a minimal Qt5 GUI and converts all `.xlsx` files to CSV.  
- For `.xls` support, more work and a different library are required.

**Let me know if you need help with `.xls` format as well!**

